#t1ada74638cd9f7a5ea94b4 ^"Otherworldly Steed" DEF {
            EXTENDS ^"Summoned Creature"
            PROPERTIES {
                ^"Name" STRING "Otherworldly Steed"
                ^"Size" STRING "Large"
                ^"Type" STRING "Celestial, Fey, or Fiend (Your Choice)"
                ^"Alignment" STRING "Neutral"
                ^"Abilities" DEF {
                    ^"Strength" INTEGER 18
                    ^"Dexterity" INTEGER 12
                    ^"Constitution" INTEGER 14
                    ^"Intelligence" INTEGER 6
                    ^"Wisdom" INTEGER 12
                    ^"Charisma" INTEGER 8
                }
                ^"Armor Class" STRING "10 + 1 per spell level"
                ^"Hit Points" STRING "5 + 10 per spell level (the steed has a number of Hit Dice [d10s] equal to the spell's level)"
                ^"Speed" DEF {
                    ^"Walk" INTEGER 60
                    ^"Conditional" LIST OF STRING ["Fly 60 ft. (requires level 4+ spell)"]
                }
                ^"Saving Throws" DEF {
                    ^"Str" INTEGER 4
                    ^"Dex" INTEGER 1
                    ^"Con" INTEGER 2
                    ^"Int" INTEGER -2
                    ^"Wis" INTEGER 1
                    ^"Cha" INTEGER -1
                }
                ^"Senses" DEF {
                    ^"Passive Perception" INTEGER 11
                }
                ^"Languages" STRING "Telepathy 1 mile (works only with you)"
                ^"Challenge Rating" STRING "None"
                ^"Experience Points" INTEGER 0
                ^"Proficiency Bonus" STRING "equals your Proficiency Bonus"
            }
            FEATURES {
                #t7df81b71ee61bd1bb116fa ^"Life Bond" DEF {
                    EXTENDS ^"Stat Block Feature"
                    ^"Category" STRING "Trait"
                    ^"Description" STRING "When you regain Hit Points from a level 1+ spell, the steed regains the same number of Hit Points if you're within 5 feet of it."
                }
                #te11a0f4da91cdb7b895b98 ^"Otherworldly Slam" DEF {
                    EXTENDS ^"Stat Block Feature"
                    ^"Category" STRING "Action"
                    ^"Description" STRING "Melee Attack Roll: Bonus equals your spell attack modifier, reach 5 ft. Hit: 1d8 plus the spell's level of Radiant (Celestial), Psychic (Fey), or Necrotic (Fiend) damage."
                }
                #te455e61e69890a9b492220 ^"Fell Glare (Fiend Only; Recharges after a Long Rest)" DEF {
                    EXTENDS ^"Stat Block Feature"
                    ^"Category" STRING "Bonus Action"
                    ^"Description" STRING "Wisdom Saving Throw: DC equals your spell save DC, one creature within 60 feet the steed can see. Failure: The target has the Frightened condition until the end of your next turn."
                }
                #ta28f849e5aac5d13a6cde0 ^"Fey Step (Fey Only; Recharges after a Long Rest)" DEF {
                    EXTENDS ^"Stat Block Feature"
                    ^"Category" STRING "Bonus Action"
                    ^"Description" STRING "The steed teleports, along with its rider, to an unoccupied space of your choice up to 60 feet away from itself."
                }
                #te9248dbd95f7850286e3ac ^"Healing Touch (Celestial Only; Recharges after a Long Rest)" DEF {
                    EXTENDS ^"Stat Block Feature"
                    ^"Category" STRING "Bonus Action"
                    ^"Description" STRING "One creature within 5 feet of the steed regains a number of Hit Points equal to 2d8 plus the spell's level."
                }
            }
        }

#tfd6fac45734682f19bb36c ^"Giant Insect" DEF {
            EXTENDS ^"Summoned Creature"
            PROPERTIES {
                ^"Name" STRING "Giant Insect"
                ^"Size" STRING "Large"
                ^"Type" STRING "Beast"
                ^"Alignment" STRING "Unaligned"
                ^"Abilities" DEF {
                    ^"Strength" INTEGER 17
                    ^"Dexterity" INTEGER 13
                    ^"Constitution" INTEGER 15
                    ^"Intelligence" INTEGER 4
                    ^"Wisdom" INTEGER 14
                    ^"Charisma" INTEGER 3
                }
                ^"Armor Class" STRING "11 + the spell's level"
                ^"Hit Points" STRING "30 + 10 for each spell level above 4"
                ^"Speed" DEF {
                    ^"Walk" INTEGER 40
                    ^"Climb" INTEGER 40
                    ^"Conditional" LIST OF STRING ["Fly 40 ft. (Wasp only)"]
