            FEATURES {
                #te2068e11d75f903c460a6f ^"Spider Climb" DEF {
                    EXTENDS ^"Stat Block Feature"
                    ^"Category" STRING "Trait"
                    ^"Description" STRING "The insect can climb difficult surfaces, including along ceilings, without needing to make an ability check."
                }
                #t0a00b80c3b65dcec5e8914 ^"Multiattack" DEF {
                    EXTENDS ^"Stat Block Feature"
                    ^"Category" STRING "Action"
                    ^"Description" STRING "The insect makes a number of attacks equal to half this spell's level (round down)."
                }
                #t5a5bc43d008fb778594f93 ^"Poison Jab" DEF {
                    EXTENDS ^"Stat Block Feature"
                    ^"Category" STRING "Action"
                    ^"Description" STRING "Melee Attack Roll: Bonus equals your spell attack modifier, reach 10 ft. Hit: 1d6 + 3 plus the spell's level Piercing damage plus 1d4 Poison damage."
                }
                #t41719125b5aae59ad0bccb ^"Web Bolt (Spider Only)" DEF {
                    EXTENDS ^"Stat Block Feature"
                    ^"Category" STRING "Action"
                    ^"Description" STRING "Ranged Attack Roll: Bonus equals your spell attack modifier, range 60 ft. Hit: 1d10 + 3 plus the spell's level Bludgeoning damage, and the target's Speed is reduced to 0 until the start of the insect's next turn."
                }
                #t000372067045a70b397cc1 ^"Venomous Spew (Centipede Only)" DEF {
                    EXTENDS ^"Stat Block Feature"
                    ^"Category" STRING "Bonus Action"
                    ^"Description" STRING "Constitution Saving Throw: Your spell save DC, one creature the insect can see within 10 feet. Failure: The target has the Poisoned condition until the start of the insect's next turn."
                }
            }
        }

