                ^"Challenge Rating" STRING "None"
                ^"Experience Points" INTEGER 0
                ^"Proficiency Bonus" STRING "equals your Proficiency Bonus"
            }
            FEATURES {
                #t396adb485c105bbd19289c ^"Shared Resistances" DEF {
                    EXTENDS ^"Stat Block Feature"
                    ^"Category" STRING "Trait"
                    ^"Description" STRING "When you summon the spirit, choose one of its Resistances. You have Resistance to the chosen damage type until the spell ends."
                }
                #t1355bba18756670b2e8a6c ^"Multiattack" DEF {
                    EXTENDS ^"Stat Block Feature"
                    ^"Category" STRING "Action"
                    ^"Description" STRING "The spirit makes a number of Rend attacks equal to half the spell's level (round down), and it uses Breath Weapon."
                }
                #tcabb420a113aab50556ac7 ^"Rend" DEF {
                    EXTENDS ^"Stat Block Feature"
                    ^"Category" STRING "Action"
                    ^"Description" STRING "Melee Attack Roll: Bonus equals your spell attack modifier, reach 10 feet. Hit: 1d6 + 4 + the spell's level Piercing damage."
                }
                #ta63205cc2bcd88cd5089b9 ^"Breath Weapon" DEF {
                    EXTENDS ^"Stat Block Feature"
                    ^"Category" STRING "Action"
                    ^"Description" STRING "Dexterity Saving Throw: DC equals your spell save DC, each creature in a 30-foot Cone. Failure: 2d6 damage of a type this spirit has Resistance to (your choice when you cast the spell). Success: Half damage."
                }
            }
        }

